 for name,h in g['evidence'].items():assert sha(ROOT/name)==h
 out=ROOT/'releases/project-closeout-20261124';out.mkdir(exist_ok=False);manifest={'schema_version':1,'status':'ENGINEERING_DELIVERY_COMPLETE_SCOPED','date':'2026-11-24','completed_scope':['RTX3060 fixed reviewed cuBLAS GEMM v0.1.3 qualified deployment','RTX3070 fixed reviewed Attention/MLA v0.1.1 existing qualified deployment','RTX3060 NCU3 realcuBLAS kernels/19metrics plus rawreport reimport and FP64 replay','Actual recovery/package rollback/backups within each released scope'],'all_original_plan_items_complete':False,'deferred_scope':['RTX3070 GEMM final production performance qualification remains rejected','Original RTX4090 C crosscard research/P6 full all-target all-operator scope not accepted','Arbitrary model source production execution not enabled','Learning review and teaching exercises deferred'],'evidence_sha256':{n:sha(ROOT/n) for n in paths.values()},'ncu':n,'ncu_tool_backup':b,'audit_environment':{'python':platform.python_version(),'numpy':np.__version__,'pandas':pd.__version__},'new_model_calls_this_closeout':0,'new_model_calls_total_against_700':190,'historical_model_calls_separate':3,'new_cuda_compilation':False,'new_formal_event_samples':0,'old_sealed_read_transferred_or_rerun':False,'production_runtime_unchanged':True,'active_gpu_or_model_jobs':False,'closeout_report':'docs/PROJECT_CLOSEOUT.md','closeout_report_sha256':sha(ROOT/'docs/PROJECT_CLOSEOUT.md'),'ncu_runbook_sha256':sha(ROOT/'docs/RTX3060_NCU.md')};(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps({'status':manifest['status'],'manifest':str(out/'manifest.json'),'ncu_kernel_launches':3,'metrics_per_launch':19,'all_original_plan_items_complete':False,'active_gpu_or_model_jobs':False}))
